//! Translate systemd units into dinit service descriptions.

use std::collections::BTreeSet;
use unitparse::{base_name, parse_timespan_secs, split_quoted, ExecLine, Unit, UnitKind};

/// First line of every generated file. Files without it are hand-written and never overwritten.
pub const MARKER: &str = "# Generated by SystemG from";

/// Environment variable that dinit fills with the readiness pipe's fd.
/// `libsd-shim`'s `sd_notify("READY=1")` writes to it.
pub const READY_FD_VAR: &str = "SYSTEMG_READY_FD";

/// systemd targets that mean "normal boot" all map onto dinit's `boot` service.
///
/// Early-boot systemd units map onto the hand-written services every SystemG
/// system provides (see `deploy/vm/guest/etc/dinit.d`): `sysinit` (filesystems,
/// udev, hostname), the udev services, and `elogind` for logind.
pub fn map_target(name: &str) -> String {
    match name {
        "multi-user.target" | "default.target" | "graphical.target" => "boot".to_string(),
        "sysinit.target" | "basic.target" => SYSINIT.to_string(),
        "systemd-udevd.service" => "udevd".to_string(),
        "systemd-udev-trigger.service" | "systemd-udev-settle.service" => {
            "udev-trigger".to_string()
        }
        "systemd-logind.service" => "elogind".to_string(),
        // The console logins every SystemG system runs (deploy/vm/guest/etc/dinit.d).
        "getty@tty1.service" => "getty-tty1".to_string(),
        "serial-getty@ttyS0.service" | "serial-getty@ttyAMA0.service" | "console-getty.service" => {
            "getty-serial".to_string()
        }
        other => base_name(other).to_string(),
    }
}

/// The early-boot service every generated service depends on, like systemd's
/// implicit `Requires=sysinit.target` (`DefaultDependencies=yes`).
pub const SYSINIT: &str = "sysinit";

/// The D-Bus bus service (system bus, or the session bus in a user manager).
pub const BUS: &str = "dbus";

/// Where generated services write their stdout/stderr.
pub const LOG_DIR: &str = "/var/log/systemg";

/// Translated output for one unit.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct DinitService {
    /// dinit service name.
    pub name: String,
    /// Contents of the dinit service file.
    pub text: String,
    /// `(file name, contents)` of an env-file to write next to it, if any.
    pub env_file: Option<(String, String)>,
    /// dinit services this one should be enabled under (`[Install] WantedBy=`).
    pub wanted_by: Vec<String>,
    /// Options that could not be expressed and were dropped.
    pub warnings: Vec<String>,
}

/// Keys the translator understands. Anything else in `[Service]` is reported.
const HANDLED_SERVICE_KEYS: &[&str] = &[
    "Type",
    "ExecStart",
    "ExecStartPre",
    "ExecStop",
    "ExecReload",
    "PIDFile",
    "Restart",
    "RestartSec",
    "TimeoutStartSec",
    "TimeoutStopSec",
    "TimeoutSec",
    "User",
    "WorkingDirectory",
    "Environment",
    "EnvironmentFile",
    "KillSignal",
    "RemainAfterExit",
    "NotifyAccess",
    "KillMode",
    "StandardOutput",
    "StandardError",
    "SyslogIdentifier",
    "Group",
    "RuntimeDirectory",
    "RuntimeDirectoryMode",
    "RuntimeDirectoryPreserve",
    "StateDirectory",
    "StateDirectoryMode",
    "CacheDirectory",
    "CacheDirectoryMode",
    "LogsDirectory",
    "LogsDirectoryMode",
    "ConfigurationDirectory",
    "ConfigurationDirectoryMode",
];
const HANDLED_UNIT_KEYS: &[&str] = &[
    "Description",
    "Documentation",
    "Requires",
    "Wants",
    "After",
    "Before",
    "BindsTo",
    "PartOf",
    "Requisite",
    "Conflicts",
    "DefaultDependencies",
    "ConditionPathExists",
];

/// Translate a `.service` or `.target` unit.
///
/// `socket` is the matching `.socket` unit, if one exists.
/// `exists` reports whether a dinit service name will exist after generation;
/// dependencies on anything else are dropped (dinit refuses to load services
/// that depend on missing ones, systemd silently ignores them).
pub fn translate(
    unit: &Unit,
    socket: Option<&Unit>,
    exists: &dyn Fn(&str) -> bool,
) -> DinitService {
    let name = map_target(&unit.name);
    let mut out = DinitService {
        name: name.clone(),
        ..Default::default()
    };
    let mut lines: Vec<String> = vec![format!("{MARKER} {}", unit.name)];
    if let Some(d) = unit.get("Unit", "Description") {
        lines.push(format!("# {d}"));
    }

    match unit.kind() {
        UnitKind::Target => lines.push("type = internal".into()),
        UnitKind::Service => {
            service_body(unit, &name, &mut lines, &mut out, exists);
            lines.push(format!("logfile = {LOG_DIR}/{name}.log"));
        }
        _ => {
            out.warnings
                .push(format!("unsupported unit type for {}", unit.name));
            lines.push("type = internal".into());
        }
    }

    if let Some(sock) = socket {
        socket_body(sock, &mut lines, &mut out.warnings);
    }

    // Dependencies. For services, DefaultDependencies=yes implies
    // Requires/After sysinit (targets only get ordering, which dinit derives).
    let default_deps = unit.get_bool("Unit", "DefaultDependencies").unwrap_or(true);
    if unit.kind() == UnitKind::Service && default_deps && name != SYSINIT && exists(SYSINIT) {
        lines.push(format!("depends-on = {SYSINIT}"));
    }
    // The system bus. Under systemd every normal service starts after
    // sockets.target, so dbus.socket is already listening and the bus is
    // reachable; Type=dbus / BusName= services also require it outright.
    let needs_bus =
        unit.get("Service", "Type") == Some("dbus") || unit.get("Service", "BusName").is_some();
    if unit.kind() == UnitKind::Service && name != BUS && exists(BUS) {
        if needs_bus {
            lines.push(format!("depends-on = {BUS}"));
            lines.push(format!("after = {BUS}"));
        } else if default_deps {
            lines.push(format!("waits-for = {BUS}"));
            lines.push(format!("after = {BUS}"));
        }
    }
    // Units this one must start *before*. A dinit dependency always starts
    // first, so Wants=/Requires= on one of these (legal in systemd: "pull it
    // in, but order me ahead of it") would be a cycle; keep only the ordering.
    let before: BTreeSet<String> = unit
        .list("Unit", "Before")
        .iter()
        .map(|d| map_target(d))
        .collect();
    let dep = |key: &str, dinit_key: &str, lines: &mut Vec<String>, warnings: &mut Vec<String>| {
        for d in unit.list("Unit", key) {
            let target = map_target(&d);
            if target == name || target == "boot" {
                continue; // `boot` depends on us, never the other way round
            }
            if dinit_key != "before" && before.contains(&target) {
                continue;
            }
            if exists(&target) {
                lines.push(format!("{dinit_key} = {target}"));
            } else {
                warnings.push(format!("{key}={d}: no such unit, dropped"));
            }
        }
    };
    dep("Requires", "depends-on", &mut lines, &mut out.warnings);
    dep("BindsTo", "depends-on", &mut lines, &mut out.warnings);
    dep("Requisite", "depends-on", &mut lines, &mut out.warnings);
    dep("Wants", "waits-for", &mut lines, &mut out.warnings);
    dep("After", "after", &mut lines, &mut out.warnings);
    dep("Before", "before", &mut lines, &mut out.warnings);

    for (k, _) in unit.entries("Unit") {
        if !HANDLED_UNIT_KEYS.contains(&k)
            && !k.starts_with("Condition")
            && !k.starts_with("Assert")
        {
            out.warnings.push(format!("[Unit] {k}= ignored"));
        }
    }
    if unit.kind() != UnitKind::Service && !unit.list("Unit", "Conflicts").is_empty() {
        out.warnings
            .push("Conflicts= on a non-service unit ignored".into());
    }

    let mut wanted: Vec<String> = unit
        .list("Install", "WantedBy")
        .into_iter()
        .chain(unit.list("Install", "RequiredBy"))
        .map(|t| map_target(&t))
        .collect();
    wanted.dedup();
    out.wanted_by = wanted;

    // Drop repeated lines (e.g. the same dependency via two keys).
    let mut seen = BTreeSet::new();
    lines.retain(|l| l.starts_with('#') || seen.insert(l.clone()));
    out.text = lines.join("\n") + "\n";
    out
}

fn service_body(
    unit: &Unit,
    name: &str,
    lines: &mut Vec<String>,
    out: &mut DinitService,
    exists: &dyn Fn(&str) -> bool,
) {
    let ty = unit
        .get("Service", "Type")
        .unwrap_or(if unit.get("Service", "BusName").is_some() {
            "dbus"
        } else {
            "simple"
        });
    let starts: Vec<ExecLine> = unit
        .values("Service", "ExecStart")
        .iter()
        .filter_map(|s| ExecLine::parse(s))
        .collect();
    let pres: Vec<ExecLine> = unit
        .values("Service", "ExecStartPre")
        .iter()
        .filter_map(|s| ExecLine::parse(s))
        .collect();
    let env_files: Vec<(bool, String)> = unit
        .values("Service", "EnvironmentFile")
        .iter()
        .map(|f| match f.strip_prefix('-') {
            Some(p) => (true, p.to_string()),
            None => (false, f.clone()),
        })
        .collect();

    let pid_file = unit.get("Service", "PIDFile");
    let dinit_type = match ty {
        "simple" | "exec" | "idle" => "process",
        "notify" | "notify-reload" => {
            lines.push(format!("ready-notification = pipevar:{READY_FD_VAR}"));
            "process"
        }
        "dbus" => {
            out.warnings
                .push("Type=dbus treated as simple (ready once started)".into());
            "process"
        }
        "forking" if pid_file.is_some() => "bgprocess",
        "forking" => {
            out.warnings
                .push("Type=forking without PIDFile=: run as scripted, process not tracked".into());
            "scripted"
        }
        "oneshot" => "scripted",
        other => {
            out.warnings
                .push(format!("Type={other} unknown, treated as simple"));
            "process"
        }
    };
    lines.insert(1, format!("type = {dinit_type}"));

    // Conflicts=X: starting this service stops X (GDM stops the tty1 getty so
    // its login screen can take that VT). dinit has no conflicts setting, so
    // stop X from the launch wrapper, in the system or user manager as we run.
    let mut setup = Vec::new();
    for c in unit.list("Unit", "Conflicts") {
        let target = map_target(&c);
        if target != name && exists(&target) && !target.ends_with("shutdown") {
            setup.push(format!(
                "if [ \"$(id -u)\" = 0 ]; then dinitctl stop {target}; else dinitctl --user stop {target}; fi >/dev/null 2>&1 || true"
            ));
        }
    }
    setup.extend(directory_setup(unit));
    let launch = Launch {
        env_files,
        setup,
        user: unit.get("Service", "User").map(str::to_string),
        group: unit.get("Service", "Group").map(str::to_string),
        notify_proxy: matches!(ty, "notify" | "notify-reload"),
    };

    if starts.is_empty() {
        if ty != "oneshot" {
            out.warnings.push("no ExecStart=".into());
        }
    } else {
        // oneshot may have several ExecStart lines; they run in order like ExecStartPre.
        let (main, extra_pre) = if dinit_type == "scripted" {
            let (last, rest) = starts.split_last().unwrap();
            (last.clone(), rest.to_vec())
        } else {
            if starts.len() > 1 {
                out.warnings
                    .push("multiple ExecStart= on non-oneshot service; using the last".into());
            }
            (starts.last().unwrap().clone(), Vec::new())
        };
        let all_pre: Vec<ExecLine> = pres.into_iter().chain(extra_pre).collect();
        let (cmd, run_as) = launch.command(&main, &all_pre);
        lines.push(format!("command = {cmd}"));
        if let Some(u) = run_as {
            lines.push(format!("run-as = {u}"));
        }
    }

    if let Some(stop) = unit.get("Service", "ExecStop").and_then(ExecLine::parse) {
        if stop.argv.iter().any(|a| a.contains("MAINPID")) {
            // dinit already signals the main process on stop.
            out.warnings
                .push("ExecStop= using $MAINPID dropped; dinit sends term-signal instead".into());
        } else {
            let stop_launch = Launch {
                setup: Vec::new(),
                notify_proxy: false,
                ..launch.clone()
            };
            let (cmd, _) = stop_launch.command_forced_shell(&stop);
            lines.push(format!("stop-command = {cmd}"));
        }
    }
    if unit.get("Service", "ExecReload").is_some() {
        out.warnings
            .push("ExecReload= not supported by dinit; `systemctl reload` will restart".into());
    }
    if let Some(p) = pid_file.filter(|_| dinit_type == "bgprocess") {
        lines.push(format!("pid-file = {p}"));
    }

    match unit.get("Service", "Restart").unwrap_or("no") {
        "no" => lines.push("restart = false".into()),
        "always" => lines.push("restart = true".into()),
        other => {
            out.warnings
                .push(format!("Restart={other} approximated as always"));
            lines.push("restart = true".into());
        }
    }
    if let Some(Some(s)) = unit
        .get("Service", "RestartSec")
        .and_then(parse_timespan_secs)
    {
        lines.push(format!("restart-delay = {}", fmt_secs(s)));
    }
    let timeout = |k: &str| {
        unit.get("Service", k)
            .or(unit.get("Service", "TimeoutSec"))
            .and_then(parse_timespan_secs)
    };
    if let Some(t) = timeout("TimeoutStartSec") {
        lines.push(format!(
            "start-timeout = {}",
            t.map(fmt_secs).unwrap_or_else(|| "0".into())
        ));
    }
    if let Some(t) = timeout("TimeoutStopSec") {
        lines.push(format!(
            "stop-timeout = {}",
            t.map(fmt_secs).unwrap_or_else(|| "0".into())
        ));
    }
    if let Some(d) = unit.get("Service", "WorkingDirectory") {
        match d.strip_prefix('-').unwrap_or(d) {
            "~" => out.warnings.push("WorkingDirectory=~ ignored".into()),
            d => lines.push(format!("working-dir = {d}")),
        }
    }
    if let Some(sig) = unit.get("Service", "KillSignal") {
        lines.push(format!("term-signal = {}", sig.trim_start_matches("SIG")));
    }

    let env: Vec<String> = unit
        .values("Service", "Environment")
        .iter()
        .flat_map(|v| split_quoted(v).unwrap_or_default())
        .filter(|kv| kv.contains('='))
        .collect();
    if !env.is_empty() {
        let file = format!("systemg-env/{name}.env");
        lines.push(format!("env-file = {file}"));
        out.env_file = Some((file, env.join("\n") + "\n"));
    }

    for (k, _) in unit.entries("Service") {
        if !HANDLED_SERVICE_KEYS.contains(&k) && k != "BusName" {
            out.warnings.push(format!("[Service] {k}= ignored"));
        }
    }
    out.warnings.dedup();
}

fn socket_body(sock: &Unit, lines: &mut Vec<String>, warnings: &mut Vec<String>) {
    let streams = sock.list("Socket", "ListenStream");
    match streams.as_slice() {
        [path] if path.starts_with('/') => {
            lines.push(format!("socket-listen = {path}"));
            if let Some(mode) = sock.get("Socket", "SocketMode") {
                lines.push(format!("socket-permissions = {mode}"));
            }
            if let Some(u) = sock.get("Socket", "SocketUser") {
                lines.push(format!("socket-uid = {u}"));
            }
            if let Some(g) = sock.get("Socket", "SocketGroup") {
                lines.push(format!("socket-gid = {g}"));
            }
        }
        [] => warnings.push(format!("{}: no ListenStream=, socket ignored", sock.name)),
        _ => warnings.push(format!(
            "{}: dinit supports one unix socket per service; socket activation disabled",
            sock.name
        )),
    }
}

/// Where SystemG's helper binaries live in the guest.
pub const LIBEXEC: &str = "/usr/libexec/systemg";

/// How a service's processes are launched.
#[derive(Clone)]
struct Launch {
    /// `EnvironmentFile=` entries: (optional, path).
    env_files: Vec<(bool, String)>,
    /// Shell lines run as root first (RuntimeDirectory= etc.).
    setup: Vec<String>,
    user: Option<String>,
    group: Option<String>,
    /// Run under sg-notify-proxy so `$NOTIFY_SOCKET` readiness reaches dinit.
    notify_proxy: bool,
}

impl Launch {
    /// Returns the dinit `command` and, when no shell wrapper is needed, the
    /// user for dinit's own `run-as`.
    ///
    /// A `/bin/sh -c` wrapper is used when there are pre-commands, environment
    /// files, setup steps or `$VAR` references. It always `exec`s the main
    /// program, so dinit tracks the right PID. Inside it, privileges are
    /// dropped with `setpriv` so setup can still run as root.
    fn command(&self, main: &ExecLine, pre: &[ExecLine]) -> (String, Option<String>) {
        let has_vars = main
            .argv
            .iter()
            .chain(pre.iter().flat_map(|p| &p.argv))
            .any(|a| a.contains('$'));
        if pre.is_empty() && self.env_files.is_empty() && self.setup.is_empty() && !has_vars {
            let argv = self.proxied(main.argv.clone());
            return (join_argv(&argv), self.user.clone());
        }
        self.wrapped(main, pre)
    }

    fn command_forced_shell(&self, main: &ExecLine) -> (String, Option<String>) {
        if self.env_files.is_empty() && !main.argv.iter().any(|a| a.contains('$')) {
            return (join_argv(&main.argv), None);
        }
        self.wrapped(main, &[])
    }

    fn wrapped(&self, main: &ExecLine, pre: &[ExecLine]) -> (String, Option<String>) {
        let mut script = Vec::new();
        for (optional, f) in &self.env_files {
            let q = sh_quote(f);
            if *optional {
                script.push(format!("if [ -r {q} ]; then set -a; . {q}; set +a; fi"));
            } else {
                script.push(format!("set -a; . {q}; set +a"));
            }
        }
        script.extend(self.setup.iter().cloned());
        for p in pre {
            let cmd = self.as_user(&p.argv, p.privileged);
            script.push(if p.ignore_failure {
                format!("{cmd} || true")
            } else {
                format!("{cmd} || exit 1")
            });
        }
        script.push(format!(
            "exec {}",
            self.as_user(&main.argv, main.privileged)
        ));
        let argv = self.proxied(vec!["/bin/sh".into(), "-c".into(), script.join("; ")]);
        (join_argv(&argv), None)
    }

    fn proxied(&self, mut argv: Vec<String>) -> Vec<String> {
        if self.notify_proxy {
            argv.insert(0, format!("{LIBEXEC}/sg-notify-proxy"));
        }
        argv
    }

    /// A shell command line, dropping to `User=`/`Group=` unless privileged (`+`/`!`).
    fn as_user(&self, argv: &[String], privileged: bool) -> String {
        let cmd = argv
            .iter()
            .map(|a| sh_word(a))
            .collect::<Vec<_>>()
            .join(" ");
        match (&self.user, privileged) {
            (Some(u), false) => {
                let g = self
                    .group
                    .clone()
                    .map(|g| sh_quote(&g))
                    .unwrap_or_else(|| format!("\"$(id -gn {})\"", sh_quote(u)));
                format!(
                    "setpriv --reuid={} --regid={g} --init-groups -- {cmd}",
                    sh_quote(u)
                )
            }
            _ => cmd,
        }
    }
}

/// `RuntimeDirectory=` and friends: create the directories before start.
fn directory_setup(unit: &Unit) -> Vec<String> {
    const KINDS: &[(&str, &str)] = &[
        ("RuntimeDirectory", "/run"),
        ("StateDirectory", "/var/lib"),
        ("CacheDirectory", "/var/cache"),
        ("LogsDirectory", "/var/log"),
        ("ConfigurationDirectory", "/etc"),
    ];
    let user = unit.get("Service", "User");
    let group = unit.get("Service", "Group");
    let mut out = Vec::new();
    for (key, base) in KINDS {
        let mode = unit.get("Service", &format!("{key}Mode")).unwrap_or("0755");
        for d in unit.list("Service", key) {
            let d = d.split(':').next().unwrap_or(&d); // ignore the `:symlink` form's target
            let path = sh_quote(&format!("{base}/{d}"));
            out.push(format!("mkdir -p {path}"));
            out.push(format!("chmod {} {path}", sh_quote(mode)));
            if let Some(u) = user {
                let owner = match group {
                    Some(g) => format!("{}:{}", sh_quote(u), sh_quote(g)),
                    None => format!("{}:\"$(id -gn {})\"", sh_quote(u), sh_quote(u)),
                };
                out.push(format!("chown {owner} {path}"));
            }
        }
    }
    out
}

/// One argument as systemd would expand it: a bare `$VAR` splits into words,
/// `${VAR}` or `$VAR` inside text stays one word.
fn sh_word(a: &str) -> String {
    let bare_var = a
        .strip_prefix('$')
        .is_some_and(|v| !v.is_empty() && v.chars().all(|c| c.is_ascii_alphanumeric() || c == '_'));
    if bare_var {
        a.to_string()
    } else if a.contains('$') {
        format!(
            "\"{}\"",
            a.replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace('`', "\\`")
        )
    } else {
        sh_quote(a)
    }
}

/// Quote argv for a dinit `command =` line (double quotes, backslash escapes).
fn join_argv(argv: &[String]) -> String {
    argv.iter()
        .map(|a| {
            let a = a.replace('$', "$$"); // dinit substitutes $VAR itself
            if !a.is_empty()
                && !a
                    .chars()
                    .any(|c| c.is_whitespace() || matches!(c, '"' | '\\' | '\'' | '#'))
            {
                a.clone()
            } else {
                format!("\"{}\"", a.replace('\\', "\\\\").replace('"', "\\\""))
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn sh_quote(s: &str) -> String {
    if !s.is_empty()
        && s.chars()
            .all(|c| c.is_ascii_alphanumeric() || "/._-=:,+@%".contains(c))
    {
        s.to_string()
    } else {
        format!("'{}'", s.replace('\'', "'\\''"))
    }
}

fn fmt_secs(s: f64) -> String {
    if s.fract() == 0.0 {
        format!("{}", s as u64)
    } else {
        format!("{s}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn all(_: &str) -> bool {
        true
    }

    #[test]
    fn simple_service() {
        let u = Unit::parse(
            "foo.service",
            "[Unit]\nDescription=Foo\nAfter=network.target\nWants=bar.service\n\
             [Service]\nExecStart=/usr/bin/foo --flag \"two words\"\nRestart=always\nRestartSec=2\n\
             User=foo\nEnvironment=A=1 \"B=two words\"\n[Install]\nWantedBy=multi-user.target\n",
        )
        .unwrap();
        let s = translate(&u, None, &all);
        assert!(s.text.contains("type = process"), "{}", s.text);
        assert!(s
            .text
            .contains("command = /usr/bin/foo --flag \"two words\""));
        assert!(s.text.contains("restart = true"));
        assert!(s.text.contains("restart-delay = 2"));
        assert!(s.text.contains("run-as = foo"));
        assert!(s.text.contains("after = network"));
        assert!(s.text.contains("waits-for = bar"));
        assert_eq!(s.wanted_by, vec!["boot"]);
        assert_eq!(s.env_file.unwrap().1, "A=1\nB=two words\n");
        assert!(s.warnings.is_empty(), "{:?}", s.warnings);
    }

    #[test]
    fn notify_uses_ready_pipe() {
        let u = Unit::parse("n.service", "[Service]\nType=notify\nExecStart=/bin/n\n").unwrap();
        let s = translate(&u, None, &all);
        assert!(s
            .text
            .contains("ready-notification = pipevar:SYSTEMG_READY_FD"));
    }

    #[test]
    fn forking_with_pre() {
        let u = Unit::parse(
            "nginx.service",
            "[Service]\nType=forking\nPIDFile=/run/nginx.pid\nExecStartPre=-/usr/sbin/nginx -t\n\
             ExecStart=/usr/sbin/nginx -g 'daemon on;'\n",
        )
        .unwrap();
        let s = translate(&u, None, &all);
        assert!(s.text.contains("type = bgprocess"));
        assert!(s.text.contains("pid-file = /run/nginx.pid"));
        assert!(
            s.text.contains(r#"command = /bin/sh -c "/usr/sbin/nginx -t || true; exec /usr/sbin/nginx -g 'daemon on;'""#),
            "{}",
            s.text
        );
    }

    #[test]
    fn missing_deps_are_dropped() {
        let u = Unit::parse(
            "a.service",
            "[Unit]\nRequires=ghost.service\n[Service]\nExecStart=/bin/a\n",
        )
        .unwrap();
        let s = translate(&u, None, &|_| false);
        assert!(!s.text.contains("ghost"));
        assert!(s.warnings.iter().any(|w| w.contains("ghost")));
    }

    #[test]
    fn socket_activation() {
        let svc = Unit::parse("d.service", "[Service]\nExecStart=/bin/d\n").unwrap();
        let sock = Unit::parse(
            "d.socket",
            "[Socket]\nListenStream=/run/d.sock\nSocketMode=0660\n",
        )
        .unwrap();
        let s = translate(&svc, Some(&sock), &all);
        assert!(s.text.contains("socket-listen = /run/d.sock"));
        assert!(s.text.contains("socket-permissions = 0660"));
    }

    #[test]
    fn oneshot_multiple_execstart() {
        let u = Unit::parse(
            "o.service",
            "[Service]\nType=oneshot\nExecStart=/bin/a\nExecStart=/bin/b\n",
        )
        .unwrap();
        let s = translate(&u, None, &all);
        assert!(s.text.contains("type = scripted"));
        assert!(
            s.text
                .contains(r#"command = /bin/sh -c "/bin/a || exit 1; exec /bin/b""#),
            "{}",
            s.text
        );
    }

    #[test]
    fn logind_maps_to_elogind() {
        assert_eq!(map_target("systemd-logind.service"), "elogind");
        let u = Unit::parse(
            "lightdm.service",
            "[Unit]\nAfter=systemd-user-sessions.service systemd-logind.service\nWants=systemd-logind.service\n\
             [Service]\nExecStart=/usr/sbin/lightdm\n",
        )
        .unwrap();
        let s = translate(&u, None, &|n| n == "elogind" || n == SYSINIT);
        assert!(s.text.contains("after = elogind"), "{}", s.text);
        assert!(s.text.contains("waits-for = elogind"), "{}", s.text);
        assert!(!s.text.contains("systemd-logind"));
    }

    #[test]
    fn wants_and_before_same_unit_is_not_a_cycle() {
        let u = Unit::parse(
            "systemd-remount-fs.service",
            "[Unit]\nDefaultDependencies=no\nWants=local-fs-pre.target\nBefore=local-fs-pre.target\n\
             [Service]\nType=oneshot\nExecStart=/bin/true\n",
        )
        .unwrap();
        let s = translate(&u, None, &all);
        assert!(s.text.contains("before = local-fs-pre"), "{}", s.text);
        assert!(!s.text.contains("waits-for = local-fs-pre"), "{}", s.text);
    }

    #[test]
    fn services_start_after_the_bus() {
        let exists = |n: &str| n == BUS || n == SYSINIT;
        // Type=dbus (polkit, udisks2, accounts-daemon): hard requirement.
        let u = Unit::parse("polkit.service", "[Service]\nType=dbus\nBusName=org.freedesktop.PolicyKit1\nExecStart=/usr/lib/polkit-1/polkitd --no-debug\n").unwrap();
        let s = translate(&u, None, &exists);
        assert!(
            s.text.contains("depends-on = dbus") && s.text.contains("after = dbus"),
            "{}",
            s.text
        );
        // Plain service: ordered after the bus, like after sockets.target.
        let u = Unit::parse("cron.service", "[Service]\nExecStart=/usr/sbin/cron -f\n").unwrap();
        let s = translate(&u, None, &exists);
        assert!(
            s.text.contains("waits-for = dbus") && s.text.contains("after = dbus"),
            "{}",
            s.text
        );
        // Early boot (DefaultDependencies=no): no bus dependency.
        let u = Unit::parse(
            "networking.service",
            "[Unit]\nDefaultDependencies=no\n[Service]\nType=oneshot\nExecStart=/sbin/ifup -a\n",
        )
        .unwrap();
        let s = translate(&u, None, &exists);
        assert!(!s.text.contains("dbus"), "{}", s.text);
    }

    /// Debian's gdm3.service: its login screen takes over tty1.
    #[test]
    fn gdm_conflicts_stop_the_tty1_getty() {
        let u = Unit::parse(
            "gdm.service",
            "[Unit]\nDescription=GNOME Display Manager\nConflicts=getty@tty1.service\nAfter=getty@tty1.service\n\
             Conflicts=plymouth-quit.service\nAfter=systemd-user-sessions.service\n\
             [Service]\nExecStartPre=/usr/share/gdm/generate-config\nExecStart=/usr/sbin/gdm3\nKillMode=mixed\n\
             Restart=always\nRestartSec=1s\nBusName=org.gnome.DisplayManager\nEnvironmentFile=-/etc/default/locale\n\
             [Install]\nAlias=display-manager.service\n",
        )
        .unwrap();
        let exists = |n: &str| ["getty-tty1", "dbus", SYSINIT].contains(&n);
        let s = translate(&u, None, &exists);
        assert!(s.text.contains("dinitctl stop getty-tty1"), "{}", s.text);
        assert!(s.text.contains("after = getty-tty1"), "{}", s.text);
        assert!(!s.text.contains("plymouth"), "{}", s.text);
        assert!(
            s.text.contains("depends-on = dbus"),
            "BusName= needs the bus: {}",
            s.text
        );
        assert!(s.text.contains("exec /usr/sbin/gdm3"), "{}", s.text);
    }
}
